#!/usr/bin/env python3
"""Write the narration transcript from speaker notes and deck/audio/manifest.json."""
import hashlib
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import audio

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "NARRATION-TRANSCRIPT.generated.md"
DISCLAIMER = (
    "**Generated by `make` from the speaker notes in `src/`. This file is overwritten "
    "on every build. Do not edit it. To change the narration, edit the spoken part of "
    "the note in `src/NN-*.md`, or edit a copy of this file and ask an agent/maintainer "
    "to propagate the change back into `src/`, then run `make && make audio`.**"
)


def clock(seconds):
    whole = int(round(seconds))
    minutes, secs = divmod(whole, 60)
    return f"{minutes:02d}:{secs:02d}"


def slides():
    found = []
    for line in (ROOT / "src" / "ORDER").read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        path = ROOT / "src" / line
        if not path.is_file():
            raise SystemExit("Invalid slide entry")
        lines = path.read_text().splitlines()
        title = anchor = None
        region = []
        for item in lines:
            if title is None:
                match = re.match(r"^# (.*?) \{([^}]+)\}\s*$", item)
                if match:
                    title, attrs = match.groups()
                    anchor = re.search(r"(?:^|\s)#(\S+)", attrs).group(1)
                continue
            if item.startswith("## "):
                break
            region.append(item)
        notes = re.search(r"^::: (?:notes|\{\.notes\})\n(.*?)\n:::", "\n".join(region), re.M | re.S)
        body = notes.group(1) if notes else ""
        spoken = re.split(r"(?m)^[ \t]*\*\*More:\*\*[ \t]*$", body)[0].strip()
        number = path.name.split("-", 1)[0]
        found.append((number, anchor, title, spoken, body))
    return found


def durations(rows):
    manifest_path = ROOT / "deck" / "audio" / "manifest.json"
    manifest = json.loads(manifest_path.read_text()) if manifest_path.is_file() else {}
    used = []
    for number, anchor, title, spoken, body in rows:
        entry = manifest.get(anchor) or {}
        text = audio.narration(body) + "\n"
        digest = hashlib.sha256(text.encode()).hexdigest()
        clip = ROOT / "deck" / entry.get("file", "")
        fresh = bool(entry) and entry.get("text_hash") == digest and clip.is_file()
        if fresh:
            seconds = float(entry["duration"])
        else:
            seconds = len(audio.narration(body).split()) / 150 * 60
        used.append((number, anchor, title, spoken, seconds, fresh))
    return used


def render():
    rows = durations(slides())
    parts = [DISCLAIMER, ""]
    cursor = 0.0
    estimated = 0
    for number, _anchor, title, spoken, seconds, fresh in rows:
        mark = "" if fresh else " (est.)"
        if not fresh:
            estimated += 1
        parts.append(f"## [{clock(cursor)}] {number} · {title}{mark}")
        parts.append("")
        parts.append(spoken if spoken else "(no spoken text)")
        parts.append("")
        cursor += seconds
    source = "audio manifest" if estimated == 0 else f"audio manifest, {estimated} estimated"
    parts.append(f"**Total:** {clock(cursor)} ({cursor:.4f} s, {source})")
    parts.append("")
    return "\n".join(parts)


def main():
    text = render()
    check = "--check" in sys.argv
    if check:
        current = OUT.read_text() if OUT.is_file() else None
        if current != text:
            raise SystemExit("transcript: NARRATION-TRANSCRIPT.generated.md is stale")
        print("transcript: committed file matches")
        return
    OUT.write_text(text)
    print(f"transcript: {text.count(chr(10) + '## ')} slides -> {OUT.name}")


if __name__ == "__main__":
    main()
